# Reference objectives (#375): one file per problem, `ext/MetaData/references/<problem>.toml`,
# written by `tools/references/update.jl` from the results of the convergence tests, one
# table per modeling and scheme, `[<modeling>.<scheme>]`: the modelings are independent, each
# has its own grid, configurations and references (#435). Read into the field
# `:reference_objective` of the metadata, `modeling => scheme => entry`, a field
# generated by tools (`Metadata.METADATA_SCHEMA.generated`), filled below once the metadata
# is loaded.
const REFERENCES_PATH = joinpath(Metadata.METADATA_PATH, "references")
# The fields of a table, and how each is read: a type, or a function of the TOML value.
const REFERENCE_FIELDS = (
    value=Float64,
    grid_size=Int,
    parameters=String,
    source=Symbol,
    agreement=Bool,
    spread=Float64,
    run=String,
    # the known solutions (#378): the objectives of the distinct solutions reached, best first
    solutions=tables -> Float64[t["objective"] for t in tables],
)

"""
Relative gap below which two objectives are the same solution (#378): above the accuracy of
the solvers at the tolerance of the tests (about 1e-6 at `tol = 1e-8`), below the gap between
the known local solutions (1.6e-4 on `mountain_car`). Used to group the solutions reached,
to say whether the configurations agree, and to say which solution a solve reached.
"""
const SAME_SOLUTION = 1e-5

"""Relative gap of `a` to `b` (absolute when `b` is zero)."""
_relative_gap(a, b) = abs(a - b) / (iszero(b) ? 1 : abs(b))
# a new directory changes `METADATA_PATH`, already a dependency
isdir(REFERENCES_PATH) && Base.include_dependency(REFERENCES_PATH)

function _invalid_reference(problem, name, file; got, expected)
    return CTBase.Exceptions.IncorrectArgument(
        "invalid reference objective $(name) of $(problem)";
        got,
        expected,
        suggestion="write $(file) again with tools/references/update.jl",
    )
end

function _references(
    problem::Symbol, file::AbstractString=joinpath(REFERENCES_PATH, "$(problem).toml")
)
    isfile(file) || return nothing
    Base.include_dependency(file)
    names = [spec.name for spec in Modelings.MODELING_SPECS]
    modelings = Pair{Symbol,NamedTuple}[]
    for (modeling, schemes) in TOML.parsefile(file)
        Symbol(modeling) in names && schemes isa AbstractDict || throw(
            _invalid_reference(
                problem,
                modeling,
                file;
                got="a table $(modeling)",
                expected="a table per modeling, among $(join(names, ", "))",
            ),
        )
        push!(modelings, Symbol(modeling) => _scheme_entries(problem, schemes, file))
    end
    return NamedTuple(modelings)
end

# the tables of one modeling, one per scheme
function _scheme_entries(problem::Symbol, schemes::AbstractDict, file::AbstractString)
    entries = Pair{Symbol,NamedTuple}[]
    for (scheme, table) in schemes
        table isa AbstractDict || throw(
            _invalid_reference(
                problem, scheme, file; got="a $(typeof(table))", expected="a table"
            ),
        )
        values = map(keys(REFERENCE_FIELDS)) do key
            haskey(table, string(key)) || throw(
                _invalid_reference(
                    problem,
                    scheme,
                    file;
                    got="no field $(key)",
                    expected="the fields $(join(keys(REFERENCE_FIELDS), ", "))",
                ),
            )
            return REFERENCE_FIELDS[key](table[string(key)])
        end
        # the known solutions with how they were obtained (#409), best first; none for a
        # file written before #409
        found = [
            _numerical_reference(problem, Symbol(scheme), Int(table["grid_size"]), s) for
            s in table["solutions"]
        ]
        references = NumericalReference[r for r in found if !isnothing(r)]
        length(references) == length(found) || empty!(references)
        push!(
            entries,
            Symbol(scheme) => NamedTuple{(keys(REFERENCE_FIELDS)..., :references)}((
                values..., references
            )),
        )
    end
    return NamedTuple(entries)
end

for problem in Metadata.PROBLEM_NAMES
    references = _references(problem)
    isnothing(references) ||
        (Metadata.METADATA_STORAGE[problem][:reference_objective] = references)
end

"""
The default discretization of a solve in the modeling of a backend, the one of its
references: the trapezoidal rule, but for ModelingToolkit, solved by single shooting.
"""
_default_scheme(::Modelings.AbstractModelBackend) = :trapeze
_default_scheme(::Modelings.ModelingToolkitBackend) = :shooting_single

# the table of `problem` for the modeling of `backend`, `grid_size` and `scheme`, or nothing
function _entry(problem::Symbol, backend, grid_size::Int, scheme::Symbol)
    tables = get(Metadata.problem_metadata(problem), :reference_objective, nothing)
    isnothing(tables) && return nothing
    schemes = get(tables, Modelings._modeling_spec(backend).name, nothing)
    isnothing(schemes) && return nothing
    entry = get(schemes, scheme, nothing)
    (isnothing(entry) || entry.grid_size != grid_size) && return nothing
    return entry
end

"""
$(TYPEDSIGNATURES)

Return the reference objective of `problem` in the modeling of `backend`, discretized on
`grid_size` steps with `scheme`, or `nothing` when it has none for this discretization.

The modelings are independent: each has its reference objectives, computed from its own
convergence tests by `tools/references/update.jl`, the best objective among the solves that
converged. They are stored in `problem_metadata(problem)[:reference_objective]`, with how
they were obtained. The defaults are the grid of the problem in the modeling
(`grid_size_data(problem, backend)`) and its discretization (the trapezoidal rule, single
shooting for ModelingToolkit).

# Example

```julia-repl
julia> OptimalControlProblems.reference_objective(:beam, JuMPBackend())
8.889...
```
"""
function reference_objective(
    problem::Symbol,
    backend::Modelings.AbstractModelBackend;
    grid_size::Int=Metadata.grid_size_data(problem, backend),
    scheme::Symbol=_default_scheme(backend),
)
    entry = _entry(problem, backend, grid_size, scheme)
    return isnothing(entry) ? nothing : entry.value
end

"""
$(TYPEDSIGNATURES)

Return the analytic solution of the continuous `problem` for `parameters` (merged with the
default ones), or `nothing` when none is known for them: a named tuple with `state` and
`control`, functions of the time, the `objective`, and its `source`.

It is the solution of the continuous problem: the objective of a discretized problem differs
from it by the discretization error, which the reference objective includes.

# Example

```julia-repl
julia> OptimalControlProblems.reference_solution_data(:beam).objective
8.88888888888889
```
"""
function reference_solution_data(
    problem::Symbol, parameters::Union{Nothing,NamedTuple}=nothing
)
    solution = get(Metadata.problem_metadata(problem), :reference_solution, nothing)
    isnothing(solution) && return nothing
    return solution(Metadata.parameters_data(problem, parameters))
end

"""
$(TYPEDSIGNATURES)

Which known solution of `problem` in the modeling of `backend` the objective `objective`
is, for the discretization on `grid_size` steps with `scheme` (#378): `:best` (the reference
objective), `:local` (another known solution), `:new` (none of them), or `nothing` when it
has no reference for this discretization. Two objectives are the same solution within a
relative `OptimalControlProblems.SAME_SOLUTION`.
"""
function solution_kind(
    problem::Symbol,
    backend::Modelings.AbstractModelBackend,
    objective::Real;
    grid_size::Int=Metadata.grid_size_data(problem, backend),
    scheme::Symbol=_default_scheme(backend),
)
    entry = _entry(problem, backend, grid_size, scheme)
    isnothing(entry) && return nothing
    _relative_gap(objective, entry.value) <= SAME_SOLUTION && return :best
    any(s -> _relative_gap(objective, s) <= SAME_SOLUTION, entry.solutions) && return :local
    return :new
end

"""
$(TYPEDSIGNATURES)

The known solutions of `problem` in the modeling of `backend`, discretized on `grid_size`
steps with `scheme`, best first, each with how it was obtained (#409); empty when it has no
reference for this discretization. The first one is the reference objective.

# Example

```julia-repl
julia> ref = first(OptimalControlProblems.references(:beam, JuMPBackend()))
julia> ref.solver, ref.options.tol, ref.status
```
"""
function references(
    problem::Symbol,
    backend::Modelings.AbstractModelBackend;
    grid_size::Int=Metadata.grid_size_data(problem, backend),
    scheme::Symbol=_default_scheme(backend),
)
    entry = _entry(problem, backend, grid_size, scheme)
    return isnothing(entry) ? NumericalReference[] : entry.references
end

"""
$(TYPEDSIGNATURES)

The best known solution of `problem` in the modeling of `backend`, discretized on
`grid_size` steps with `scheme`, with how it was obtained, or `nothing`: its objective is
`reference_objective(problem, backend)`.
"""
function best_reference(
    problem::Symbol,
    backend::Modelings.AbstractModelBackend;
    grid_size::Int=Metadata.grid_size_data(problem, backend),
    scheme::Symbol=_default_scheme(backend),
)
    found = references(problem, backend; grid_size, scheme)
    return isempty(found) ? nothing : first(found)
end

"""
$(TYPEDSIGNATURES)

The analytic solution of the continuous `problem` for `parameters` (merged with the default
ones) as an [`AnalyticReference`](@ref), or `nothing` when none is known for them.
"""
function analytic_reference(problem::Symbol, parameters::Union{Nothing,NamedTuple}=nothing)
    solution = reference_solution_data(problem, parameters)
    isnothing(solution) && return nothing
    return AnalyticReference(
        problem,
        Metadata.parameters_data(problem, parameters),
        Float64(solution.objective),
        solution.state,
        solution.control,
        solution.source,
    )
end
